#include <iostream>

using namespace std;

/**
 * Problem: 22161 - Euclid Problem
 * 
 * 解題思路：
 * 1. 給定 A 和 B，尋找 X, Y, D 使得 AX + BY = D，且 D = gcd(A, B)。
 * 2. 使用擴展歐幾里得演算法 (Extended Euclidean Algorithm)。
 * 3. 擴展歐幾里得在計算 gcd 的同時，利用遞迴回溯的過程中更新 X 和 Y。
 * 4. 對於 gcd(a, b)，設其結果為 (d, x', y')，滿足 ax' + by' = d。
 *    當呼叫 gcd(b, a%b) 時，得到 (d, x, y)，滿足 bx + (a%b)y = d。
 *    代入 a%b = a - floor(a/b)*b，得 bx + (a - floor(a/b)*b)y = d。
 *    整理後得 ay + b(x - floor(a/b)y) = d。
 *    故新的 x' = y, y' = x - floor(a/b)y。
 */

long long extended_gcd(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long x1, y1;
    long long d = extended_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
    return d;
}

int main() {
    long long a, b;
    while (cin >> a >> b) {
        long long x, y;
        long long d = extended_gcd(a, b, x, y);
        cout << x << " " << y << " " << d << endl;
    }
    return 0;
}
